import{_ as r,o,c as a,a2 as n}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"模拟盘交易","description":"","frontmatter":{},"headers":[],"relativePath":"features/sim-trading.md","filePath":"features/sim-trading.md","lastUpdated":null}'),d={name:"features/sim-trading.md"};function s(e,t,l,i,g,h){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="模拟盘交易" tabindex="-1">模拟盘交易 <a class="header-anchor" href="#模拟盘交易" aria-label="Permalink to &quot;模拟盘交易&quot;">​</a></h1><p>模拟盘通过内置的 <strong>SIM 渠道</strong> 提供一个零风险的仿真交易环境：行情与撮合都在本地模拟完成，账户数据持久化保存，关掉重开数据不丢失。它适用于：</p><ul><li>新用户熟悉平台交易操作；</li><li>手工交易练习（配合历史回放即 <a href="/features/training">操盘手训练</a>）；</li><li>策略上实盘前的模拟验证（模组用途选&quot;模拟盘&quot;）。</li></ul><h2 id="创建模拟网关" tabindex="-1">创建模拟网关 <a class="header-anchor" href="#创建模拟网关" aria-label="Permalink to &quot;创建模拟网关&quot;">​</a></h2><p>SIM 渠道同时支持行情与交易两种用途，且<strong>无需任何网关配置</strong>。建议创建一对网关：</p><h3 id="_1-模拟行情网关" tabindex="-1">1. 模拟行情网关 <a class="header-anchor" href="#_1-模拟行情网关" aria-label="Permalink to &quot;1. 模拟行情网关&quot;">​</a></h3><p><strong>网关管理 → 新建</strong>：</p><table tabindex="0"><thead><tr><th>字段</th><th>填写</th></tr></thead><tbody><tr><td>网关用途</td><td><strong>行情</strong></td></tr><tr><td>网关渠道</td><td><strong>SIM</strong></td></tr><tr><td>订阅合约</td><td>选择需要的模拟合约（平台内置 3 个模拟合约）</td></tr></tbody></table><h3 id="_2-模拟交易网关-模拟账户" tabindex="-1">2. 模拟交易网关（模拟账户） <a class="header-anchor" href="#_2-模拟交易网关-模拟账户" aria-label="Permalink to &quot;2. 模拟交易网关（模拟账户）&quot;">​</a></h3><p>再次 <strong>新建</strong>：</p><table tabindex="0"><thead><tr><th>字段</th><th>填写</th></tr></thead><tbody><tr><td>网关用途</td><td><strong>交易</strong></td></tr><tr><td>网关渠道</td><td><strong>SIM</strong></td></tr><tr><td>行情网关</td><td>绑定上面创建的 SIM 行情网关</td></tr></tbody></table><p>创建后点网关卡片的 <strong>连线</strong>，卡片出现绿色的&quot;已连接&quot;标签即表示就绪。</p><div class="tip custom-block"><p class="custom-block-title">一个 SIM 交易网关 = 一个模拟账户</p><p>想练多种策略或多人对比？多建几个 SIM 交易网关即可拥有多个互相独立的模拟账户，详见 <a href="/features/multi-account">多账户交易</a>。</p></div><h2 id="出入金" tabindex="-1">出入金 <a class="header-anchor" href="#出入金" aria-label="Permalink to &quot;出入金&quot;">​</a></h2><p>新账户需要注入虚拟资金才能交易：</p><ol><li>在 SIM 交易网关卡片右上角&quot;更多&quot;下拉中选择 <strong>出入金</strong>；</li><li>弹窗显示&quot;【账户名】账户余额&quot;；</li><li>输入 <strong>出入金额</strong>（步进 100,000；<strong>正数入金、负数出金</strong>），点击 <strong>OK</strong>。</li></ol><h2 id="手工下单" tabindex="-1">手工下单 <a class="header-anchor" href="#手工下单" aria-label="Permalink to &quot;手工下单&quot;">​</a></h2><p>桌面端所有页面底部都有<strong>交易面板</strong>，点击中间横条展开。左侧为下单区：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><strong>交易账户</strong></td><td>下拉选择用哪个账户下单（列出全部交易网关，支持多账户切换）</td></tr><tr><td>账户信息</td><td>只读显示：账户权益 / 可用金额 / 资金使用率</td></tr><tr><td><strong>交易合约</strong></td><td>只列出该账户已订阅的合约</td></tr><tr><td><strong>交易量</strong></td><td>下单手数</td></tr><tr><td><strong>价格类型</strong></td><td>市价 / 对手价 / 排队价 / 限价（限价时可编辑价格）</td></tr><tr><td><strong>价格</strong></td><td>仅限价单可输入</td></tr></tbody></table><p>三个下单按钮（按钮上直接显示按当前行情计算的委托价）：</p><ul><li>🔴 <strong>买开</strong>：开多仓</li><li>🟢 <strong>卖开</strong>：开空仓</li><li>⚪ <strong>平仓</strong>：平掉选中的持仓（先开先平 FIFO，需先在持仓列表中选中一行）</li></ul><p>交易面板左侧还有三个图标按钮：</p><ul><li><strong>浮窗模式</strong>：下单表单弹出为独立浮窗，方便拖动；</li><li><strong>显示/隐藏历史持仓线</strong>：在K线图上标注历史持仓区间（仅 SIM 账户）；</li><li><strong>账户绩效</strong>：打开绩效分析弹窗（仅 SIM 账户）。</li></ul><h2 id="账户数据标签页" tabindex="-1">账户数据标签页 <a class="header-anchor" href="#账户数据标签页" aria-label="Permalink to &quot;账户数据标签页&quot;">​</a></h2><p>交易面板右侧以标签页展示当前账户的实时数据：</p><table tabindex="0"><thead><tr><th>标签页</th><th>内容</th></tr></thead><tbody><tr><td><strong>持仓</strong></td><td>合约名称、方向、总持仓、可用持仓、开仓均价、持仓盈亏</td></tr><tr><td><strong>挂单</strong></td><td>未成交委托，带<strong>撤单</strong>按钮</td></tr><tr><td><strong>计划</strong></td><td>画线交易计划列表（入场/止损/止盈/盈亏比）</td></tr><tr><td><strong>委托</strong></td><td>当日全部委托记录</td></tr><tr><td><strong>成交</strong></td><td>当日全部成交记录</td></tr></tbody></table><h2 id="画线交易" tabindex="-1">画线交易 <a class="header-anchor" href="#画线交易" aria-label="Permalink to &quot;画线交易&quot;">​</a></h2><p>在&quot;多图同列&quot;的K线图上<strong>右键 → 画线交易</strong>，可以直接在图上画出：</p><ul><li><strong>多头 / 空头</strong>：画出入场位置即生成开仓计划；</li><li><strong>止盈 / 止损</strong>：为持仓设定离场线；</li><li><strong>交易计划</strong>：组合入场、止损、止盈，弹窗会显示盈亏比并要求确认。</li></ul><p>画线计划生成后显示在交易面板的&quot;计划&quot;标签页中，行情触线自动执行。</p><div class="warning custom-block"><p class="custom-block-title">前提</p><p>画线交易需要先在交易面板选定<strong>交易账户</strong>，否则无法提交。</p></div><h2 id="账户绩效复盘" tabindex="-1">账户绩效复盘 <a class="header-anchor" href="#账户绩效复盘" aria-label="Permalink to &quot;账户绩效复盘&quot;">​</a></h2><p>在交易面板点击&quot;账户绩效&quot;图标，打开绩效弹窗，包含三个标签页：</p><ul><li><strong>交易记录</strong>：逐笔开平仓明细；</li><li><strong>交易统计</strong>：盈亏分布、交易笔数、盈亏合计，支持按&quot;净盈亏曲线 / 合约统计&quot;切换统计口径；</li><li><strong>盈亏曲线</strong>：账户权益变化曲线。</li></ul><p>这是手工交易与操盘手训练后复盘总结的核心工具。</p><h2 id="程序化模拟交易" tabindex="-1">程序化模拟交易 <a class="header-anchor" href="#程序化模拟交易" aria-label="Permalink to &quot;程序化模拟交易&quot;">​</a></h2><p>让策略在模拟盘自动运行：新建模组时<strong>模组用途选&quot;模拟盘&quot;</strong>，绑定 SIM 交易账户即可。详见 <a href="/features/auto-trading">程序化交易</a>。</p>',37)])])}const c=r(d,[["render",s]]);export{p as __pageData,c as default};
